// AI Image Checker — client-side only, no uploads, no network calls.
// Mirrors the Python version's scoring: start at 50, thresholds 75 / 35.
// Every reason is labelled as a heuristic, not proof.

const GENERATOR_KEYWORDS = [
  "midjourney", "dall-e", "dall·e", "stable diffusion", "stable-diffusion",
  "adobe firefly", "firefly", "imagen", "flux", "ideogram", "leonardo",
  "runway", "sora", "gpt-image", "ai generated", "ai-generated",
  "generated by ai", "synthetic image",
];
// C2PA / content credentials are provenance markers, not proof of AI
// generation, so they score separately (+10) from generator keywords (+35),
// matching the Python version.
const C2PA_KEYWORDS = ["c2pa", "content credentials"];
const CAMERA_MAKES = [
  "canon", "nikon", "sony", "fujifilm", "fuji", "olympus", "panasonic",
  "leica", "pentax", "gopro", "apple", "samsung", "google",
  "hasselblad", "ricoh",
];
const SOFTWARE_KEYWORDS = [
  "adobe photoshop", "photoshop", "lightroom", "gimp", "paint.net", "affinity photo",
];

const fileInput = document.getElementById("file-input");
const dropzone = document.getElementById("dropzone");
const checkButton = document.getElementById("check-button");
const errorEl = document.getElementById("error");
const previewEl = document.getElementById("preview");
const previewImg = document.getElementById("preview-img");
const fileInfo = document.getElementById("file-info");
const emptyState = document.getElementById("empty-state");
const resultEl = document.getElementById("result");
const verdictEl = document.getElementById("verdict");
const scoreEl = document.getElementById("score");
const scoreFill = document.getElementById("score-fill");
const reasonsEl = document.getElementById("reasons");

let selectedFile = null;
let selectedDataUrl = null;

function showError(msg) {
  errorEl.textContent = msg;
  errorEl.hidden = false;
}
function clearError() {
  errorEl.textContent = "";
  errorEl.hidden = true;
}

function isImageFile(file) {
  // Some mobile browsers / formats (e.g. TIFF) report an empty MIME type,
  // so fall back to the file extension instead of rejecting the file.
  if (file.type && file.type.startsWith("image/")) return true;
  return /\.(jpe?g|png|gif|webp|bmp|tiff?|avif)$/i.test(file.name || "");
}

function onFileChosen(file) {
  clearError();
  if (!file || !isImageFile(file)) {
    showError("Please choose an image file.");
    checkButton.disabled = true;
    return;
  }
  selectedFile = file;
  // Hide any previous result until this image is checked.
  resultEl.hidden = true;
  emptyState.hidden = false;
  checkButton.disabled = true;
  const reader = new FileReader();
  reader.onload = () => {
    selectedDataUrl = reader.result;
    previewImg.src = selectedDataUrl;
    fileInfo.textContent = `${file.name} — ${(file.size / 1024).toFixed(1)} KB — ${file.type || "image"}`;
    previewEl.hidden = false;
    // Do NOT enable "Check image" yet: imageStats needs naturalWidth /
    // naturalHeight, which are 0 until the preview image has decoded.
    // Enabling early gave bogus 1x1-image statistics.
  };
  reader.onerror = () => {
    showError("Could not read this image file. Please try a different image.");
    checkButton.disabled = true;
  };
  reader.readAsDataURL(file);
}

// Enable checking only once the preview has actually loaded.
previewImg.onload = () => { checkButton.disabled = !selectedFile; };
previewImg.onerror = () => {
  showError("Could not display this image. Please try a different image file.");
  checkButton.disabled = true;
};

fileInput.addEventListener("change", () => onFileChosen(fileInput.files[0]));
dropzone.addEventListener("dragover", (e) => { e.preventDefault(); });
dropzone.addEventListener("drop", (e) => {
  e.preventDefault();
  onFileChosen(e.dataTransfer.files[0]);
});

function findKeywords(text, keywords) {
  const lower = text.toLowerCase();
  return keywords.filter((k) => lower.includes(k));
}

// Read PNG text chunks (tEXt / iTXt / zTXt) plus a plain-text scan of the
// whole file, so generator / camera strings are found even in JPEGs.
async function scanMetadata(file) {
  const buffer = await file.arrayBuffer();
  const bytes = new Uint8Array(buffer);
  let text = "";
  try {
    // Native Latin-1 decode is far faster than building a string
    // byte-by-byte, which matters for multi-megabyte photos on phones.
    if (typeof TextDecoder !== "undefined") {
      text = new TextDecoder("iso-8859-1").decode(bytes);
    } else {
      text = Array.from(bytes, (b) => String.fromCharCode(b)).join("");
    }
  } catch {
    text = "";
  }
  return {
    generator: findKeywords(text, GENERATOR_KEYWORDS),
    c2pa: findKeywords(text, C2PA_KEYWORDS).length > 0,
    camera: findKeywords(text, CAMERA_MAKES),
    software: findKeywords(text, SOFTWARE_KEYWORDS),
  };
}

function imageStats(img) {
  // Draw a small copy to a canvas and measure smoothness / saturation.
  // Weak evidence only — real photos can be smooth and vivid too.
  const maxSide = 256;
  const scale = Math.min(1, maxSide / Math.max(img.naturalWidth, img.naturalHeight));
  const w = Math.max(1, Math.round(img.naturalWidth * scale));
  const h = Math.max(1, Math.round(img.naturalHeight * scale));
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });
  ctx.drawImage(img, 0, 0, w, h);
  const data = ctx.getImageData(0, 0, w, h).data;
  let diffSum = 0, diffCount = 0, satSum = 0, pxCount = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = (y * w + x) * 4;
      const r = data[i], g = data[i + 1], b = data[i + 2];
      const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
      satSum += mx === 0 ? 0 : (mx - mn) / mx;
      pxCount++;
      if (x + 1 < w) {
        const j = i + 4;
        diffSum += Math.abs(r - data[j]) + Math.abs(g - data[j + 1]) + Math.abs(b - data[j + 2]);
        diffCount++;
      }
    }
  }
  return {
    meanNeighbourDiff: diffCount ? diffSum / diffCount / 3 : 0,
    meanSaturation: pxCount ? satSum / pxCount : 0,
  };
}

checkButton.addEventListener("click", async () => {
  if (!selectedFile) return;
  clearError();
  checkButton.disabled = true;
  checkButton.textContent = "Checking…";
  try {
    if (!previewImg.naturalWidth || !previewImg.naturalHeight) {
      throw new Error("preview image not loaded yet");
    }
    const meta = await scanMetadata(selectedFile);
    const stats = imageStats(previewImg);

    let score = 50;
    const reasons = [];

    if (meta.generator.length) {
      score += 35;
      reasons.push(`Heuristic: generator keyword found in file data (${meta.generator.join(", ")}).`);
    }
    if (meta.c2pa) {
      score += 10;
      reasons.push("Heuristic: file contains a C2PA / content-credentials marker (provenance metadata, not proof of AI generation on its own).");
    }
    // Match the Python version's mutually exclusive chain: camera, else
    // software-only, else no camera data. The old code added both the
    // software (+10) and the no-camera (+5) bonuses together.
    if (meta.camera.length) {
      score -= 25;
      reasons.push(`Heuristic: camera make found in file data (${meta.camera.join(", ")}).`);
    } else if (meta.software.length) {
      score += 10;
      reasons.push(`Heuristic: software-only provenance (${meta.software.join(", ")}), no camera make.`);
    } else {
      score += 5;
      reasons.push("Heuristic (weak): no camera make found in file data.");
    }
    // Thresholds match the Python version (< 4 smooth, > 25 textured,
    // saturation > 0.55); the old < 8 / > 0.45 thresholds were looser.
    if (stats.meanNeighbourDiff < 4) {
      score += 10;
      reasons.push("Heuristic (weak): image areas are very smooth / low-noise.");
    } else if (stats.meanNeighbourDiff > 25) {
      score -= 5;
      reasons.push("Heuristic (weak): relatively textured / noisy image.");
    }
    if (stats.meanSaturation > 0.55) {
      score += 5;
      reasons.push("Heuristic (weak): unusually high average saturation.");
    }
    if (!reasons.length) reasons.push("Heuristic: no strong metadata or image clues found.");

    score = Math.max(0, Math.min(100, Math.round(score)));
    let verdict, cls;
    if (score >= 75) { verdict = "likely AI-generated"; cls = "ai"; }
    else if (score <= 35) { verdict = "likely real / camera photo"; cls = "real"; }
    else { verdict = "uncertain"; cls = "uncertain"; }

    verdictEl.textContent = verdict;
    verdictEl.className = `verdict ${cls}`;
    scoreEl.textContent = String(score);
    scoreFill.style.width = `${score}%`;
    reasonsEl.innerHTML = "";
    reasons.forEach((r) => {
      const li = document.createElement("li");
      li.textContent = r;
      reasonsEl.appendChild(li);
    });
    emptyState.hidden = true;
    resultEl.hidden = false;
  } catch (err) {
    showError("Could not check this image. Please try a different image file.");
  } finally {
    // Only re-enable if the preview is actually loaded; otherwise the
    // previewImg.onload handler will enable it once decoding finishes.
    checkButton.disabled = !previewImg.naturalWidth;
    checkButton.textContent = "Check image";
  }
});
